1	import { type NextRequest } from "next/server";
2	import { getUser } from "@/lib/auth";
3	import { createClient } from "@/lib/supabase/server";
4	import {
5	  getBooking,
6	  getSessionByBooking,
7	  getApprovedProvider,
8	} from "@/lib/db/queries";
9	import { formatCents } from "@/lib/format";
10	import { durationLabel } from "@/lib/time";
11	import { t } from "@/lib/i18n";
